const attachmentPreview=textEl('div','','chat-attachment');attachmentPreview.hidden=true;chatForm.insertBefore(attachmentPreview,input);inputActions.append(attachButton,voiceButton,send);inputBottom.replaceChildren(inputHint,inputActions);chatForm.insertBefore(voiceStatus,inputBottom);chatForm.append(imagePicker);inputHint.textContent='可输入、语音、粘贴或拖入图片';
function syncComposer(){send.disabled=busy||(!input.value.trim()&&!pendingImage);attachButton.disabled=busy;voiceButton.disabled=busy||voiceButton.dataset.supported==='false'||voiceState==='converting'||voiceState==='requesting';inputHint.textContent=`${Math.min(input.value.length,1200)} / 1200 · 可输入、语音、粘贴或拖入图片`}
function clearPendingImage(){pendingImage=null;attachmentPreview.hidden=true;attachmentPreview.replaceChildren();syncComposer()}
function showPendingImage(){attachmentPreview.replaceChildren();if(!pendingImage){attachmentPreview.hidden=true;return}const image=document.createElement('img');image.src=pendingImage.dataUrl;image.alt='待发送图片预览';const info=textEl('span','');info.append(textEl('strong',pendingImage.name),textEl('small','已压缩 · 仅随本轮发送给 DeepSeek'));const remove=textEl('button','移除');remove.type='button';remove.setAttribute('aria-label','移除待发送图片');remove.onclick=clearPendingImage;attachmentPreview.append(image,info,remove);attachmentPreview.hidden=false;syncComposer()}
function loadLocalImage(file){return new Promise((resolve,reject)=>{const url=URL.createObjectURL(file),image=new Image();image.onload=()=>{URL.revokeObjectURL(url);resolve(image)};image.onerror=()=>{URL.revokeObjectURL(url);reject(Error('invalid image'))};image.src=url})}
async function prepareImage(file){
 if(!file||!/^image\/(jpeg|png|webp|gif)$/i.test(file.type)||file.size>8*1024*1024){$('#ai-status').textContent='请选择不超过 8 MB 的 JPG、PNG、WebP 或 GIF 图片。';return}
 attachButton.disabled=true;$('#ai-status').textContent='正在压缩图片…';
 try{const image=await loadLocalImage(file);let dataUrl='';for(const [maxSize,quality] of [[1280,.82],[1080,.72],[900,.62]]){const scale=Math.min(1,maxSize/Math.max(image.naturalWidth,image.naturalHeight)),canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round(image.naturalWidth*scale));canvas.height=Math.max(1,Math.round(image.naturalHeight*scale));const context=canvas.getContext('2d');context.fillStyle='#fff';context.fillRect(0,0,canvas.width,canvas.height);context.drawImage(image,0,0,canvas.width,canvas.height);dataUrl=canvas.toDataURL('image/jpeg',quality);if(dataUrl.length<=1850000)break}if(dataUrl.length>1850000)throw Error('too large');pendingImage={name:file.name.slice(0,80),dataUrl};showPendingImage();$('#ai-status').textContent='图片已就绪 · 发送时将使用 DeepSeek Flash 识别';}
 catch{$('#ai-status').textContent='这张图片暂时无法读取，请换一张再试。';clearPendingImage()}finally{attachButton.disabled=busy}
}
attachButton.onclick=()=>imagePicker.click();imagePicker.onchange=()=>{const file=imagePicker.files?.[0];imagePicker.value='';if(file)prepareImage(file)};
chatForm.addEventListener('dragover',event=>{if(Array.from(event.dataTransfer?.types||[]).includes('Files')){event.preventDefault();chatForm.classList.add('drop-active')}});chatForm.addEventListener('dragleave',()=>chatForm.classList.remove('drop-active'));chatForm.addEventListener('drop',event=>{event.preventDefault();chatForm.classList.remove('drop-active');const file=Array.from(event.dataTransfer?.files||[]).find(item=>item.type.startsWith('image/'));if(file)prepareImage(file)});
input.addEventListener('paste',event=>{const file=Array.from(event.clipboardData?.files||[]).find(item=>item.type.startsWith('image/'));if(file){event.preventDefault();prepareImage(file)}});
function paintVoice(state,message){voiceState=state;voiceStatus.dataset.state=state;voiceStatus.textContent=message;voiceButton.setAttribute('aria-pressed',String(state==='listening'));voiceButton.textContent=state==='listening'?'■ 停止并转文字':state==='requesting'?'◌ 等待麦克风…':state==='converting'?'◌ 云端转写中…':state==='unsupported'?'语音暂不可用':'◉ 开始听';voiceButton.setAttribute('aria-label',state==='listening'?'停止录音并转换成文字':state==='unsupported'?'语音转写当前不可用':'开始语音输入');syncComposer()}
function releaseVoiceStream(){if(voiceStream){voiceStream.getTracks().forEach(track=>track.stop());voiceStream=null}window.dispatchEvent(new CustomEvent('takagi:voice-recording',{detail:{active:false}}))}
function startBrowserSpeechFallback(){
 const SpeechInput=window.SpeechRecognition||window.webkitSpeechRecognition;voiceFallbackText='';voiceFallbackError='';if(!SpeechInput)return;
 try{voiceFallback=new SpeechInput();voiceFallback.lang='zh-CN';voiceFallback.interimResults=true;voiceFallback.continuous=true;voiceFallback.onresult=event=>{let words='';for(let i=0;i<event.results.length;i++)words+=event.results[i][0]?.transcript||'';voiceFallbackText=words.trim()};voiceFallback.onerror=event=>{voiceFallbackError=event.error||'unavailable'};voiceFallback.start()}catch{voiceFallback=null}
}
function stopBrowserSpeechFallback(){if(voiceFallback){try{voiceFallback.stop()}catch{}voiceFallback=null}}
async function transcribeVoice(blob){
 const form=new FormData();form.append('audio',blob,blob.type.includes('mp4')?'voice.m4a':blob.type.includes('ogg')?'voice.ogg':'voice.webm');
 const controller=new AbortController(),timeout=setTimeout(()=>controller.abort(),32000);let response;
 try{response=await fetch('/api/transcribe',{method:'POST',body:form,signal:controller.signal})}catch{throw Error('云端转写连接失败，请稍后重试。')}finally{clearTimeout(timeout)}
 const data=await response.json().catch(()=>({}));if(!response.ok||!data.text)throw Error(data.error||'云端转写暂时不可用。');return String(data.text).trim()
}
function stopVoice(){if(voiceRecorder&&voiceRecorder.state==='recording'){paintVoice('converting','录音已停止，正在通过云端转成文字…');voiceRecorder.stop()}}
async function startVoice(){
 if(!navigator.mediaDevices?.getUserMedia||!window.MediaRecorder){paintVoice('unsupported','当前浏览器无法录音。请使用 Chrome、Edge 或 Safari，并在地址栏允许麦克风。');voiceButton.dataset.supported='false';return}
 voiceBase=input.value.trim();voiceChunks=[];voiceFallbackText='';voiceFallbackError='';
 paintVoice('requesting','正在等待麦克风权限…');
 try{const pendingStream=navigator.mediaDevices.getUserMedia({audio:{echoCancellation:true,noiseSuppression:true,autoGainControl:true}}),timeoutToken={timeout:true};const result=await Promise.race([pendingStream,new Promise(resolve=>setTimeout(()=>resolve(timeoutToken),12000))]);if(result===timeoutToken){pendingStream.then(stream=>stream.getTracks().forEach(track=>track.stop())).catch(()=>{});paintVoice('error','没有收到麦克风授权。Codex 内置浏览器可能不支持录音，请在 Chrome、Edge 或 Safari 打开本站。');return}voiceStream=result}catch(error){const denied=error&&['NotAllowedError','SecurityError'].includes(error.name);paintVoice('error',denied?'麦克风权限未开放。请在地址栏允许后，再点一次“开始听”。':'没有找到可用麦克风，请检查系统输入设备。');return}
 const types=['audio/webm;codecs=opus','audio/webm','audio/mp4','audio/ogg;codecs=opus'];const mimeType=types.find(type=>MediaRecorder.isTypeSupported?.(type))||'';
 try{voiceRecorder=new MediaRecorder(voiceStream,mimeType?{mimeType}:undefined)}catch{releaseVoiceStream();paintVoice('unsupported','当前浏览器无法建立录音。可以继续使用键盘输入。');return}
 voiceRecorder.ondataavailable=event=>{if(event.data?.size)voiceChunks.push(event.data)};
 voiceRecorder.onerror=()=>{clearInterval(voiceTimer);stopBrowserSpeechFallback();releaseVoiceStream();paintVoice('error','录音没有完成，请重新开始。')};
 voiceRecorder.onstop=async()=>{clearInterval(voiceTimer);const blob=new Blob(voiceChunks,{type:voiceRecorder.mimeType||voiceChunks[0]?.type||'audio/webm'});stopBrowserSpeechFallback();releaseVoiceStream();$('#presence-label').textContent='她在听';if(!blob.size){paintVoice('error','没有录到声音，请重新开始。');return}try{const words=await transcribeVoice(blob);input.value=[voiceBase,words].filter(Boolean).join(voiceBase?' ':'');paintVoice('done','已由云端转成文字并写入输入框。请确认内容，再点击发送。');input.focus();input.setSelectionRange(input.value.length,input.value.length)}catch(error){if(voiceFallbackText){input.value=[voiceBase,voiceFallbackText].filter(Boolean).join(voiceBase?' ':'');paintVoice('done','云端转写暂不可用，已使用浏览器识别并写入输入框。请确认后发送。');input.focus();input.setSelectionRange(input.value.length,input.value.length)}else{const hint=voiceFallbackError?'当前浏览器也未能完成备用识别。':'当前浏览器没有可用的备用识别。';paintVoice('error',`${error.message||'云端转写暂时不可用。'} ${hint}请在 Chrome、Edge 或 Safari 打开本站；Codex 的 Quick Annotate 只会发送到 Codex。`)}}syncComposer()};
 voiceRecorder.start(500);startBrowserSpeechFallback();voiceStartedAt=Date.now();paintVoice('listening','正在录音 00:00。说完后点“停止并转文字”。');$('#presence-label').textContent='她在听你说';window.dispatchEvent(new CustomEvent('takagi:voice-recording',{detail:{active:true}}));
 voiceTimer=setInterval(()=>{const elapsed=Math.floor((Date.now()-voiceStartedAt)/1000),seconds=String(elapsed%60).padStart(2,'0');voiceStatus.textContent=`正在录音 00:${seconds}。说完后点“停止并转文字”。`;if(elapsed>=45)stopVoice()},500)
}
voiceButton.dataset.supported=navigator.mediaDevices?.getUserMedia&&window.MediaRecorder?'true':'false';
if(voiceButton.dataset.supported==='false'){inputHint.textContent='可输入、粘贴或拖入图片';paintVoice('unsupported','当前浏览器无法录音。请使用 Chrome、Edge 或 Safari，并允许麦克风。')}
voiceButton.onclick=()=>voiceState==='listening'?stopVoice():startVoice();
window.addEventListener('pagehide',()=>{clearInterval(voiceTimer);stopBrowserSpeechFallback();if(voiceRecorder?.state==='recording')voiceRecorder.stop();releaseVoiceStream()});
async function requestAI(message,image){
 const topicContext=activeTerm?{title:activeTerm.title,tag:activeTerm.tag,summary:activeTerm.summary,detail:activeTerm.detail,scene:activeTerm.scene,opening:termOpening(activeTerm)}:null;
 const controller=new AbortController(),timeout=setTimeout(()=>controller.abort(),image?30000:16000);let response;try{response=await fetch('/api/chat',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({message,image:image?.dataUrl,password:passwordInput.value,mode:aiMode,scene:activeScene,profile,modelPreference:profile.modelPreference,history:aiHistory.slice(-CHAT_CONTEXT_LIMIT),topicContext}),signal:controller.signal})}catch(error){if(error?.name==='AbortError')throw Error('在线回复等待超时');throw Error('网络连接失败')}finally{clearTimeout(timeout)}
 const data=await response.json().catch(()=>({}));if(!response.ok){const failure=Error(data.error||'在线模型暂时不可用');failure.code=data.code||'';failure.status=response.status;throw failure}try{sessionStorage.setItem('takagi-ai-password',passwordInput.value)}catch{}forgetPassword.hidden=false;passwordStatus.textContent='密码已验证并保存在当前标签页。刷新后仍可用，关闭标签页或点击“清除”后失效。';
 if(!data||typeof data.text!=='string'||!data.text.trim())throw Error('在线模型返回了空内容');
 return{text:data.text.trim(),mood:data.mood||'listening',topic:data.topic||'chat',suggestions:Array.isArray(data.suggestions)?data.suggestions.slice(0,4):[],knowledgeTags:Array.isArray(data.knowledgeTags)?data.knowledgeTags:[]};
}
