function showGlossary(){const body=document.createElement('div');body.className='term-dialog';body.append(textEl('p','这些词条区分原作背景、人物语气、生活文化、成年话题与原创情景。'));const search=document.createElement('input');search.type='search';search.placeholder='搜索词条';search.setAttribute('aria-label','搜索词条');body.append(search);const filters=document.createElement('div');filters.className='term-filters';const list=document.createElement('div');list.className='term-list';let filter='全部';function render(){list.replaceChildren();const q=search.value.trim();const shown=terms.filter(t=>(filter==='全部'||t.tag===filter)&&(!q||t.title.includes(q)||t.summary.includes(q)||t.detail.includes(q)));shown.forEach(t=>{const b=textEl('button',t.title,'term-row');b.append(textEl('small',t.tag),textEl('span',t.summary));b.onclick=()=>openTerm(t);list.append(b)});if(!shown.length)list.append(textEl('p','没有找到相关词条。'))}['全部','日本青春','原作背景','人物语气','中国校园','成年日常','关系与边界','选择与计划','兴趣与作品','情绪整理','学习与复盘','中日饮食','作息文化','天气气候','地理常识','原创互动','互动约定'].forEach(f=>{const b=textEl('button',f);b.setAttribute('aria-pressed',String(filter===f));b.onclick=()=>{filter=f;filters.querySelectorAll('button').forEach(x=>x.setAttribute('aria-pressed',String(x.textContent===f)));render()};filters.append(b)});search.oninput=render;body.append(filters,list);render();openDialog('日常词条',body);search.focus()}
